CREATE TABLE hotels(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(160) NOT NULL,address VARCHAR(500) NOT NULL,archived BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE rooms(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,hotel_id BIGINT NOT NULL REFERENCES hotels(id),number VARCHAR(30) NOT NULL,available BOOLEAN NOT NULL,times_booked BIGINT NOT NULL DEFAULT 0 CHECK(times_booked>=0),archived BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT NOT NULL DEFAULT 0,UNIQUE(hotel_id,number));
CREATE INDEX idx_rooms_hotel_available ON rooms(hotel_id,available,archived,times_booked,id);
CREATE TABLE room_lock(id INTEGER PRIMARY KEY);
INSERT INTO room_lock VALUES(1);
CREATE TABLE reservations(id UUID PRIMARY KEY,booking_id UUID NOT NULL,room_id BIGINT REFERENCES rooms(id),start_date DATE,end_date DATE,state VARCHAR(16) NOT NULL,confirmed BOOLEAN NOT NULL DEFAULT FALSE,fingerprint VARCHAR(128),created_at TIMESTAMP WITH TIME ZONE NOT NULL,CHECK(start_date IS NULL OR start_date<end_date));
CREATE INDEX idx_reservations_calendar ON reservations(room_id,state,start_date,end_date);
CREATE INDEX idx_reservations_booking ON reservations(booking_id);
CREATE TABLE cancelled_bookings(id UUID PRIMARY KEY);
